"""Compile and exercise actual server bridge commands against real JSON/files."""
from pathlib import Path
import io
import subprocess
import tempfile
import urllib.request
import zipfile

source = Path(__file__).resolve().parents[1]/'server/server-kit/core/Modules/ServerAdmin.cs'
harness = '\nusing System;\nusing System.IO;\nusing System.Text;\nusing System.Reflection;\nusing Newtonsoft.Json.Linq;\nusing PrefabEditor.Modules;\nnamespace UnityEngine { public struct Vector3 {public float x,y,z;public Vector3(float a,float b,float c){x=a;y=b;z=c;}} public struct Quaternion {public static Quaternion identity {get{return new Quaternion();}}} }\nnamespace Alta.Console {public class CommandAttribute:Attribute {public CommandAttribute(string a,string b){}}}\nnamespace Alta.Populations { public class SpawnPoint {public UnityEngine.Vector3 Position;public SpawnPoint(UnityEngine.Vector3 p,UnityEngine.Quaternion q,int i){Position=p;}} }\nnamespace HarmonyLib {public class Harmony {public Harmony(string id){} public void Patch(MethodInfo m,HarmonyMethod prefix){} public void UnpatchSelf(){}} public class HarmonyMethod {public HarmonyMethod(Type t,string name){}} public class AccessTools {public static MethodInfo Method(Type t,string name){return t.GetMethod(name);}}}\npublic enum SpawnAreaIdentifier {OriginalSpawnPoint,RespawnPoint,Home,OutsideCave}\npublic class SpawnArea {public SpawnAreaIdentifier Identifier; public void GetSpawnPosition(){}}\npublic class Player { public object PlayerController; public static Player[] AllPlayers; }\npublic class PlayerCommunicationManager {public static PlayerCommunicationManager Instance=new PlayerCommunicationManager();public int Count; public string Last;public void SendMessageToPlayer(Player p,string m,float duration){Count++;Last=m;}}\nnamespace PrefabEditor.Modules {public static class EditJson {public static string Err(string error){return new JObject(new JProperty("ok",false),new JProperty("error",error)).ToString();}}}\nclass Test {\n static void Check(bool v,string message){if(!v)throw new Exception(message);}\n static bool Ok(string s){return (bool)JObject.Parse(s)["ok"];}\n static object[] Spawn(SpawnAreaIdentifier id){var args=new object[]{new SpawnArea{Identifier=id},0,null}; bool native=(bool)typeof(ServerSpawn).GetMethod("Prefix",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args);return new object[]{native,args[2]};}\n static void Main(string[] args){\n  Directory.CreateDirectory(args[0]);ServerSpawn.Initialize(args[0],s=>{});\n  Check((bool)Spawn(SpawnAreaIdentifier.RespawnPoint)[0],"default spawn unchanged");\n  Check(!Ok(EditorAdminModule.SetServerSpawn(float.NaN,0,0)),"NaN rejected");\n  Check(Ok(EditorAdminModule.SetServerSpawn(1,2,3)),"save spawn");\n  ServerSpawn.Shutdown();ServerSpawn.Initialize(args[0],s=>{});\n  foreach(var id in new[]{SpawnAreaIdentifier.OriginalSpawnPoint,SpawnAreaIdentifier.RespawnPoint}){\n   var result=Spawn(id);Check(!(bool)result[0],"override restored");Check(((Alta.Populations.SpawnPoint)result[1]).Position.y==2,"destination preserved");\n  }\n  Check((bool)Spawn(SpawnAreaIdentifier.Home)[0] && (bool)Spawn(SpawnAreaIdentifier.OutsideCave)[0],"homes/cave exits untouched");\n  Check(Ok(EditorAdminModule.SetServerSpawn(4,5,6)),"repeat save");\n  Check(Ok(EditorAdminModule.ResetServerSpawn()),"reset");\n  ServerSpawn.Shutdown();ServerSpawn.Initialize(args[0],s=>{});\n  Check((bool)Spawn(SpawnAreaIdentifier.RespawnPoint)[0],"reset persists");\n  Player.AllPlayers=new[]{new Player{PlayerController=new object()},null,new Player(),new Player{PlayerController=new object()}};\n  Check(Ok(EditorAdminModule.Broadcast(Convert.ToBase64String(Encoding.UTF8.GetBytes("Hello all")))),"broadcast succeeds");\n  Check(PlayerCommunicationManager.Instance.Count==2 && PlayerCommunicationManager.Instance.Last=="Hello all","all online players only");\n  Check(!Ok(EditorAdminModule.Broadcast("invalid base64")),"invalid broadcast rejected");\n  Console.WriteLine("PASS: spawn save/reload/reset, coordinate validation, scope isolation, broadcast delivery and validation");\n }\n}\n'
with tempfile.TemporaryDirectory(prefix='tavern-server-test-') as folder:
    root=Path(folder)
    package=urllib.request.urlopen('https://api.nuget.org/v3-flatcontainer/newtonsoft.json/13.0.3/newtonsoft.json.13.0.3.nupkg', timeout=30).read()
    with zipfile.ZipFile(io.BytesIO(package)) as archive:
        (root/'Newtonsoft.Json.dll').write_bytes(archive.read('lib/net45/Newtonsoft.Json.dll'))
    (root/'Test.cs').write_text(harness)
    subprocess.run([r'C:\Windows\Microsoft.NET\Framework64\v4.0.30319\csc.exe','/nologo','/out:'+str(root/'test.exe'),'/r:'+str(root/'Newtonsoft.Json.dll'),str(source),str(root/'Test.cs')],check=True)
    subprocess.run([str(root/'test.exe'),str(root/'data')],check=True)
